const item = $input.first().json;
const raw = String(item.message || '').trim();
const lower = raw.toLowerCase();

const isSlackIntent = /\bslack\b/.test(lower) && /(envi|manda|mandar|post|send|mensaje|message|avisa|notifica)/.test(lower);

let targetHint = '';
let actionMessage = '';

const quoted = raw.match(/["“”']([^"“”']{3,})["“”']/);
if (quoted) actionMessage = quoted[1].trim();

const targetMatch = raw.match(/(?:a|to)\s+([A-Za-zÀ-ÿ0-9._@\-\s]{2,60}?)(?:\s+(?:que\s+diga|diga|saying\s+that|that)|\s*:|$)/i);
if (targetMatch) targetHint = targetMatch[1].trim();

if (!actionMessage) {
  const sayMatch = raw.match(/(?:que\s+diga|diga|saying\s+that|saying)\s+(.+)$/i);
  if (sayMatch) actionMessage = sayMatch[1].trim();
}

if (!actionMessage && isSlackIntent) actionMessage = raw;

let intentType = 'general_chat';
if (isSlackIntent) intentType = 'slack_send_action';
else if (/(clickup|tarea|task|asignad|assigned)/.test(lower)) intentType = 'clickup_lookup';
else if (/(calendar|calendario|evento|eventos|meeting|reunion)/.test(lower)) intentType = 'calendar_lookup';

return [{ json: { ...item, intent_type: intentType, action_target_hint: targetHint, action_message: actionMessage } }];

const item = $input.first();
const data = item.json || {};
const templateHtml = String(data.email_template_html || data.html || "").trim();
const markdownCandidate = String(data.generated_email_markdown || data.message || data.enriched_message || "").trim();
const fallbackBody = markdownCandidate
  ? `<p style="margin:0 0 12px 0;">${markdownCandidate.replace(/\n/g, "<br />")}</p>`
  : `<p style="margin:0;">No body content provided.</p>`;
const htmlBody = templateHtml && templateHtml.includes("{{body_html}}")
  ? templateHtml.replace(/\{\{body_html\}\}/g, fallbackBody)
  : fallbackBody;
return [{ json: { ...data, template_intercept_applied: true, intercepted_email_html: htmlBody, composio_email_payload: { body: htmlBody, is_html: true } } }];
